const stateRows={es:'Respondida|Sin responder|Cerrar|Tus respuestas se guardan.|Reiniciar reemplaza las respuestas sin terminar. Los informes completados se conservan.',fr:'Répondu|Sans réponse|Fermer|Vos réponses restent enregistrées.|Recommencer remplace les réponses inachevées. Les rapports terminés sont conservés.',de:'Beantwortet|Unbeantwortet|Schließen|Ihre Antworten bleiben gespeichert.|Ein Neustart ersetzt unfertige Antworten. Fertige Berichte bleiben erhalten.',pt:'Respondida|Sem resposta|Fechar|Suas respostas ficam salvas.|Recomeçar substitui as respostas não concluídas. Relatórios concluídos são mantidos.',it:'Risposta data|Senza risposta|Chiudi|Le risposte restano salvate.|Ricominciare sostituisce le risposte incomplete. I rapporti completati restano salvati.',ru:'Есть ответ|Нет ответа|Закрыть|Ваши ответы сохраняются.|Новый тест заменит незавершённые ответы. Готовые отчёты сохранятся.',ar:'تمت الإجابة|دون إجابة|إغلاق|تبقى إجاباتك محفوظة.|البدء من جديد يستبدل الإجابات غير المكتملة. تبقى التقارير المكتملة محفوظة.',ur:'جواب دیا گیا|جواب باقی|بند کریں|آپ کے جوابات محفوظ رہیں گے۔|دوبارہ شروع کرنے سے نامکمل جوابات بدل جائیں گے۔ مکمل رپورٹس محفوظ رہیں گی۔',bn:'উত্তর দেওয়া|উত্তর বাকি|বন্ধ করুন|আপনার উত্তর সেভ থাকবে।|আবার শুরু করলে অসমাপ্ত উত্তর বদলে যাবে। সম্পূর্ণ রিপোর্ট সেভ থাকবে।',zh:'已回答|未回答|关闭|答案会保留。|重新开始将替换未完成的答案，已完成的报告会保留。',ja:'回答済み|未回答|閉じる|回答は保存されます。|やり直すと未完了の回答が置き換わります。完了済みレポートは残ります。',id:'Terjawab|Belum dijawab|Tutup|Jawaban Anda tetap tersimpan.|Memulai ulang mengganti jawaban yang belum selesai. Laporan selesai tetap disimpan.',tr:'Yanıtlandı|Yanıtsız|Kapat|Yanıtlarınız kayıtlı kalır.|Yeniden başlatmak tamamlanmamış yanıtları değiştirir. Tamamlanan raporlar korunur.',vi:'Đã trả lời|Chưa trả lời|Đóng|Câu trả lời vẫn được lưu.|Bắt đầu lại sẽ thay thế câu trả lời chưa hoàn tất. Báo cáo đã hoàn thành vẫn được giữ.',ko:'답변 완료|미답변|닫기|답변은 저장됩니다.|다시 시작하면 미완료 답변이 바뀝니다. 완료된 보고서는 유지됩니다.',mr:'उत्तर दिले|उत्तर बाकी|बंद करा|तुमची उत्तरे जतन राहतील.|पुन्हा सुरू केल्यास अपूर्ण उत्तरे बदलतील. पूर्ण अहवाल जतन राहतील.',ta:'பதிலளித்தது|பதில் இல்லை|மூடவும்|உங்கள் பதில்கள் சேமிக்கப்படும்.|மீண்டும் தொடங்கினால் முடிக்காத பதில்கள் மாற்றப்படும். முடித்த அறிக்கைகள் இருக்கும்.',te:'సమాధానం ఇచ్చారు|సమాధానం లేదు|మూసివేయండి|మీ సమాధానాలు సేవ్ అవుతాయి.|మళ్లీ ప్రారంభిస్తే అసంపూర్తి సమాధానాలు మారతాయి. పూర్తి నివేదికలు అలాగే ఉంటాయి.'};
for(const [code,row] of Object.entries(stageRows)){const pack=questionLocales[code],stages=row.split('|'),states=stateRows[code].split('|');pack.stages=stages;pack.states=states;['Start','Settle in','Explore','Reflect','Discover'].forEach((key,i)=>pack.ui[key]=stages[i]);for(const key of ['One small thought at a time.','Find your gentle rhythm.','Let curiosity lead the way.','Notice your own patterns.','Your reflections are ready.','Choosing an answer moves to the next question automatically. You can also use number keys 1 to 5. Use Previous and Next to browse without changing your answer.'])pack.ui[key]=pack.ui['Select to move on, or use the arrows.'];Object.assign(pack.ui,{'Jump to a question':pack.ui.Questions,'Close dialog':states[2],'A few answers are still missing.':`${pack.ui.Questions} — ${states[1]}`,'Answer remaining questions →':pack.ui['Continue test'],'Keep reviewing':pack.ui['Continue test'],'Start a fresh assessment?':pack.ui['Start again'],'Keep my place':pack.ui['Continue test'],'Continue assessment':pack.ui['Continue test']})}
const gentleCaptions={es:'Una respuesta a la vez.',fr:'Une réponse à la fois.',de:'Eine Antwort nach der anderen.',pt:'Uma resposta de cada vez.',it:'Una risposta alla volta.',ru:'По одному ответу за раз.',ar:'إجابة واحدة في كل مرة.',ur:'ایک وقت میں ایک جواب۔',bn:'একবারে একটি উত্তর।',zh:'一次回答一题。',ja:'一度に一つずつ。',id:'Satu jawaban setiap langkah.',tr:'Her seferinde tek bir yanıt.',vi:'Mỗi lần một câu trả lời.',ko:'한 번에 하나씩.',mr:'एका वेळी एक उत्तर.',ta:'ஒரு நேரத்தில் ஒரு பதில்.',te:'ఒకసారి ఒక సమాధానం.'};
for(const [code,caption] of Object.entries(gentleCaptions)){const pack=questionLocales[code];for(const key of ['One small thought at a time.','Find your gentle rhythm.','Let curiosity lead the way.','Notice your own patterns.','Your reflections are ready.'])pack.ui[key]=caption;pack.ui['Keep reviewing']=pack.states[2];pack.ui['Keep my place']=pack.states[2]}
